from django.shortcuts import render
from django.core.paginator import Paginator, EmptyPage
from .models import Branch
from .utils import get_branch_map_link

def contact_page(request):
    branches = Branch.objects.all()
    paginator = Paginator(branches, 5)
    page = request.GET.get('page', 1)
    branches_on_page = paginator.page(page)

    # Generate map links
    map_links = []
    for branch in branches_on_page:
        map_link = get_branch_map_link(branch)
        map_links.append(f'<a href="{map_link}" target="_blank">{branch.name}</a>')

    # Generate message form
    message_form = f'<form method="post" action="{get_branch_map_link(branches[0])}">{render("contact_form", {"branch": branches[0]})}</form>'

    return render(request, 'contact/contact.html', {
        'branches_on_page': branches_on_page,
        'map_links': map_links,
        'message_form': message_form
    })
```

