def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    fees = {}
    for area, distance in areas_km.items():
        if distance < 0:
            continue
        fee = int(distance * 10)  # Convert to shillings
        fees[area] = fee
    return fees
```

