def rider_plan(stops_km: list[float], rush_hour: bool) -> int:
    # Calculate total distance
    total_distance = sum(stops_km)

    # Calculate total rider minutes
    if rush_hour:
        # Assume 1.5x riders for rush hour
        return int(total_distance * 1.5)
    else:
        # Assume 1x riders for non-rush hour
        return int(total_distance)
